// The pure layer of the Office editors: the zip reader and the guard that says, before a file opens, what a light editor would lose.
// Files are generated by lib-test-files.mjs, none is stored. No DSH, no disk, no network.
//
//   node packages/kybernos-office/test-guard.mjs
import { listParts, readPart, readText } from './zip-lite.mjs'
import { FORMATS, formatOf, inspect } from './office-guard.mjs'
import { docx, xlsx, zip } from './lib-test-files.mjs'

let failed = 0
const check = (label, ok, detail) => {
  console.log((ok ? '  ok   ' : '  FAIL ') + label + (ok || detail === undefined ? '' : '  -- ' + detail))
  if (!ok) failed += 1
}
const code = (fn) => { try { fn(); return null } catch (e) { return e && e.code } }
const levels = (r) => Object.fromEntries(r.losses.map((l) => [l.code, l.level]))

// ── the zip reader ─────────────────────────────────────────────────────────────
{
  const z = zip({ 'a.txt': 'plain', 'dir/b.txt': 'deflated ' + 'x'.repeat(500), 'c.txt': 'plain again' })
  const parts = listParts(z)
  check('the parts are listed, stored and deflated alike', parts.size === 3 && parts.get('a.txt').method === 0 && parts.get('dir/b.txt').method === 8)
  check('a stored part reads back', readText(z, parts, 'a.txt') === 'plain' && readText(z, parts, 'c.txt') === 'plain again')
  check('a deflated part reads back', readText(z, parts, 'dir/b.txt') === 'deflated ' + 'x'.repeat(500))
  check('a part that is not there is null', readPart(z, parts, 'nope') === null && readText(z, parts, 'nope') === null)
  check('a name with accents survives', listParts(zip({ 'é.txt': 'x' })).has('é.txt'))
  check('plain text is not a zip', code(() => listParts(Buffer.from('this is not a zip file at all, only text'))) === 'not-a-zip')
  check('a short buffer and a non-buffer are not zips', code(() => listParts(Buffer.alloc(5))) === 'not-a-zip' && code(() => listParts('PK')) === 'not-a-zip')
  check('a zip cut in half is refused, not read', code(() => listParts(z.subarray(0, Math.floor(z.length / 2)))) === 'not-a-zip')
  const b = Buffer.from(zip({ 'big.bin': 'x', 'bomb.bin': 'y' }))
  const bp = listParts(b)
  bp.set('bomb.bin', { ...bp.get('bomb.bin'), size: 70 * 1024 * 1024 })
  check('a part declared over 64 MB is refused before it is inflated', code(() => readPart(b, bp, 'bomb.bin')) === 'part-too-big')
  const lie = listParts(zip({ 'x.bin': 'ab', 'y.bin': 'a'.repeat(200) }))
  const real = zip({ 'x.bin': 'ab', 'y.bin': 'a'.repeat(200) })
  lie.set('y.bin', { ...lie.get('y.bin'), size: 10 })
  check('a part that inflates to something honest still reads (the declared size is not trusted for the text)', readText(real, lie, 'y.bin') === 'a'.repeat(200))
}

// ── which names open in a light editor ─────────────────────────────────────────
{
  check('docx and xlsx open, in any case', formatOf('/a/b.docx') === 'docx' && formatOf('REPORT.XLSX') === 'xlsx' && formatOf('x.y.Docx') === 'docx')
  check('the formats of the other slices do not open yet', formatOf('deck.pptx') === null && formatOf('old.doc') === null && formatOf('old.xls') === null && formatOf('a.odt') === null)
  check('no extension, a dotfile, a lookalike: nothing', formatOf('docx') === null && formatOf('') === null && formatOf(null) === null && formatOf('a.docx.exe') === null && formatOf('a.constructor') === null)
  check('each format names its editor', FORMATS.docx.editor === 'doc' && FORMATS.xlsx.editor === 'sheet')
}

// ── the guard: a file that is what it says ─────────────────────────────────────
{
  const d = inspect('docx', docx())
  check('a plain docx opens with nothing to say', d.ok === true && d.losses.length === 0 && d.block === false, JSON.stringify(d))
  const x = inspect('xlsx', xlsx())
  check('a plain xlsx opens with nothing to say', x.ok === true && x.losses.length === 0 && x.block === false, JSON.stringify(x))
}

// ── the guard: what the 2026-11-03 spike measured as lost ──────────────────────
{
  const l = inspect('xlsx', xlsx({ chart: true, comment: true, validation: true, macro: true }))
  check('xlsx: chart, comment, validation and macro are losses, and the person is asked first', l.ok && l.block === true && levels(l).chart === 'loss' && levels(l).comment === 'loss' && levels(l).validation === 'loss' && levels(l).macro === 'loss', JSON.stringify(l))
  const n = inspect('xlsx', xlsx({ image: true, pivot: true, filter: true }))
  check('xlsx: pictures, pivot tables, filters are « untested »: a notice, no block', n.ok && n.block === false && levels(n).image === 'untested' && levels(n).pivot === 'untested' && levels(n).filter === 'untested', JSON.stringify(n))
  const r = inspect('docx', docx({ tracked: true, comment: true }))
  check('docx: tracked changes and comments are kept but cannot be reviewed: a notice, no block', r.ok && r.block === false && levels(r)['tracked-changes'] === 'review' && levels(r).comment === 'review', JSON.stringify(r))
  const u = inspect('docx', docx({ image: true, field: true, control: true }))
  check('docx: pictures, fields, content controls are « untested »', u.ok && u.block === false && levels(u).image === 'untested' && levels(u).field === 'untested' && levels(u)['content-control'] === 'untested', JSON.stringify(u))
  check('docx: a macro is a loss', inspect('docx', docx({ macro: true })).block === true)
  check('the counts say how many (two tracked runs)', inspect('docx', docx({ tracked: true })).losses.find((e) => e.code === 'tracked-changes').count === 2)
}

// ── the guard: a file that is not what it says ─────────────────────────────────
{
  check('a zip that is not a docx is refused with the reason', inspect('docx', xlsx()).reason === 'not-a-docx' && inspect('xlsx', docx()).reason === 'not-a-xlsx')
  check('text with a .docx name is refused', inspect('docx', Buffer.from('hello, this is plain text pretending to be a document')).reason === 'not-a-zip')
  check('an empty file is refused', inspect('xlsx', Buffer.alloc(0)).ok === false)
  check('a format that has no light editor is refused', inspect('pptx', docx()).reason === 'unsupported-format')
  check('a refusal never throws', (() => { try { inspect('docx', zip({ 'word/document.xml': 'x' }).subarray(0, 40)); return true } catch (e) { return false } })())
}

process.exit(failed === 0 ? 0 : 1)
